/**
 * Android 专用的 sharp 替身（纯 JS，无原生依赖）。
 *
 * 为什么需要：sharp 依赖 libvips 原生二进制；官方预编译只有 darwin/linux-gnu/win32，
 * 没有 Android（bionic libc）版本，Android 上 `import sharp` 直接失败。
 *
 * ⚠️ v1.15.1 重写（这版之前是「只解析文件头、像素变换全部原样返回」）：
 * 那个版本造成了两类真机故障，根因都是**替身撒谎**——返回的字节和声明的格式/尺寸不一致：
 *
 *   症状 A（会话被永久毒死）：坏 PNG（文件头合法、IDAT 损坏）能一路穿过管线被上传，
 *     被 provider 拒收 400；此后该图片作为 tool_result 留在会话历史里，**每次请求都复现**。
 *     原因：唯一的完整解码防线是 `detectImage()` 里的 `await image.raw().toBuffer()`，
 *     而旧替身的 `raw().toBuffer()` 直接回吐原始字节 —— **像素从未被解码**，损坏未被发现。
 *
 *   症状 B（合法截图发不出去，报成 TRANSPORT）：需要缩小/重编码的非 JPEG 图片必然失败。
 *     `encodingLadder()` 选 image/jpeg（因为旧 `metadataOf()` 从不返回 hasAlpha），
 *     旧替身的 `jpeg()` 是空操作、`toBuffer()` 回吐原始 PNG 字节，而 `encode()`
 *     把输出标注成 image/jpeg → `verifyRequestImage()` 发现「声明 JPEG / 实为 PNG」
 *     → 抛 AttachmentError → 因为 AttachmentError 不是 LlmError，被适配器
 *     包成 "DeepSeek Messages transport failed" / TRANSPORT（原始原因完全丢失）。
 *     对照：相机 JPEG 走同一条路时替身回吐 JPEG、声明也是 JPEG → 断言通过，
 *     所以这个坑**只对「需要缩放的非 JPEG 图片」发作**（PNG/WebP/GIF）。
 *
 * 现在的语义（诚实优先）：
 *  - **PNG 有真正的编解码**：解析全部 chunk（含 CRC 校验）、inflate、反滤波，
 *    支持 IHDR 位深 1/2/4/8/16、颜色类型 0/2/3/4/6、隔行 0/1；编码输出 8 位 sRGB（必要时带 alpha）。
 *    → `raw().toBuffer()` 会**真的解码**，损坏的 PNG 在入库时就被拒；
 *    → `resize()` 真的缩放，PNG 需要缩小也能正常发出。
 *  - **其它格式（JPEG/WebP/GIF）仍是原样直通**：无原生库时无法在纯 JS 里重编码。
 *    但**绝不再谎报格式** —— `toBuffer()` 一律返回 `info.mediaType = 真实格式`，
 *    调用方据此声明，因此「声明 == 实际字节」始终成立，provider 侧不会再因类型不符被拒。
 *  - `metadataOf()` 现在返回**真实的 hasAlpha**（PNG 看 IHDR 颜色类型），
 *    不再让 `encodingLadder()` 一律选 JPEG。
 */
import zlib from "node:zlib";

/** 把各种输入形态统一成 Buffer。 */
function toBytes(input) {
	if (Buffer.isBuffer(input)) return input;
	if (input instanceof Uint8Array || Array.isArray(input)) return Buffer.from(input);
	if (input !== null && typeof input === "object" && input.data !== undefined) return toBytes(input.data);
	throw new TypeError("sharp-shim: 不支持的图像输入类型");
}

//#region 文件头探测（不解码像素，用于快速识别格式与尺寸）

/**
 * 从文件头解析栅格图的格式与固有尺寸，不解码像素。
 * @param buf - 完整编码字节。
 * @returns 格式与宽高，无法识别时返回 null。
 */
function probeImageBytes(buf) {
	if (buf.length >= 24 && buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47) {
		return { format: "png", width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) };
	}
	if (buf.length >= 4 && buf[0] === 0xff && buf[1] === 0xd8) {
		let offset = 2;
		while (offset + 9 < buf.length) {
			if (buf[offset] !== 0xff) {
				offset++;
				continue;
			}
			const marker = buf[offset + 1];
			const length = buf.readUInt16BE(offset + 2);
			if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
				return { format: "jpeg", width: buf.readUInt16BE(offset + 7), height: buf.readUInt16BE(offset + 5) };
			}
			offset += 2 + length;
		}
	}
	if (buf.length >= 30 && buf.toString("ascii", 0, 4) === "RIFF" && buf.toString("ascii", 8, 12) === "WEBP") {
		const chunk = buf.toString("ascii", 12, 16);
		if (chunk === "VP8X") return { format: "webp", width: buf.readUIntLE(24, 3) + 1, height: buf.readUIntLE(27, 3) + 1 };
		if (chunk === "VP8 ") return { format: "webp", width: buf.readUInt16LE(26) & 0x3fff, height: buf.readUInt16LE(28) & 0x3fff };
		if (chunk === "VP8L" && buf.length >= 25) {
			const bits = buf.readUInt32LE(21);
			return { format: "webp", width: (bits & 0x3fff) + 1, height: ((bits >> 14) & 0x3fff) + 1 };
		}
	}
	if (buf.length >= 10 && buf.toString("ascii", 0, 3) === "GIF") {
		return { format: "gif", width: buf.readUInt16LE(6), height: buf.readUInt16LE(8) };
	}
	return null;
}

const MEDIA_TYPES = {
	png: "image/png",
	jpeg: "image/jpeg",
	webp: "image/webp",
	gif: "image/gif"
};

//#endregion

//#region PNG 编解码（纯 JS：CRC 校验 + inflate + 反滤波 / 滤波 + deflate）

const PNG_SIGNATURE = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

/** PNG 的 CRC-32（多项式 0xedb88320）。 */
const CRC_TABLE = (() => {
	const table = new Int32Array(256);
	for (let n = 0; n < 256; n++) {
		let c = n;
		for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
		table[n] = c;
	}
	return table;
})();

function crc32(buf) {
	let c = 0xffffffff;
	for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
	return (c ^ 0xffffffff) >>> 0;
}

/** 单个通道的字节数（用于反滤波的 bpp）。 */
function channelsFor(colourType) {
	switch (colourType) {
		case 0: return 1; // 灰度
		case 2: return 3; // RGB
		case 3: return 1; // 调色板（每像素 1 个索引）
		case 4: return 2; // 灰度 + alpha
		case 6: return 4; // RGBA
		default: throw new Error(`sharp-shim: PNG 颜色类型 ${colourType} 不支持`);
	}
}

/** Adam7 隔行的 7 趟几何。 */
const ADAM7 = [
	{ x0: 0, y0: 0, dx: 8, dy: 8 },
	{ x0: 4, y0: 0, dx: 8, dy: 8 },
	{ x0: 0, y0: 4, dx: 4, dy: 8 },
	{ x0: 2, y0: 0, dx: 4, dy: 4 },
	{ x0: 0, y0: 2, dx: 2, dy: 4 },
	{ x0: 1, y0: 0, dx: 2, dy: 2 },
	{ x0: 0, y0: 1, dx: 1, dy: 2 }
];

/**
 * 解析 PNG 的全部 chunk，逐个校验 CRC。
 * 这一步就能抓住「文件头合法但内容损坏」的图（IDAT CRC 不匹配）。
 */
function readPngChunks(buf) {
	if (buf.length < 8 || !buf.subarray(0, 8).equals(PNG_SIGNATURE)) {
		throw new Error("sharp-shim: 不是 PNG（签名不匹配）");
	}
	const chunks = [];
	let offset = 8;
	let sawIhdr = false;
	let sawIend = false;
	while (offset + 12 <= buf.length) {
		const length = buf.readUInt32BE(offset);
		const type = buf.toString("ascii", offset + 4, offset + 8);
		const dataStart = offset + 8;
		const dataEnd = dataStart + length;
		if (dataEnd + 4 > buf.length) throw new Error(`sharp-shim: PNG chunk ${type} 越界（文件被截断）`);
		const data = buf.subarray(dataStart, dataEnd);
		const stored = buf.readUInt32BE(dataEnd);
		const actual = crc32(buf.subarray(offset + 4, dataEnd));
		if (stored !== actual) {
			throw new Error(
				`sharp-shim: PNG chunk ${type} 的 CRC 不匹配（存储 ${stored.toString(16)} / 实算 ${actual.toString(16)}）—— 文件已损坏`
			);
		}
		if (type === "IHDR") {
			sawIhdr = true;
			if (chunks.some((c) => c.type === "IHDR")) throw new Error("sharp-shim: PNG 出现多个 IHDR");
		}
		if (type === "IEND") {
			sawIend = true;
			chunks.push({ type, data });
			break;
		}
		chunks.push({ type, data });
		offset = dataEnd + 4;
	}
	if (!sawIhdr) throw new Error("sharp-shim: PNG 缺少 IHDR");
	if (!sawIend) throw new Error("sharp-shim: PNG 缺少 IEND（文件被截断）");
	return chunks;
}

/** 从一个扫描线缓冲里按位深取出第 i 个样本。 */
function readSample(row, index, bitDepth) {
	if (bitDepth === 8) return row[index];
	if (bitDepth === 16) return row[index * 2]; // 取高字节（16 → 8 位）
	const perByte = 8 / bitDepth;
	const byte = row[(index / perByte) | 0];
	const shift = 8 - bitDepth * ((index % perByte) + 1);
	return (byte >> shift) & ((1 << bitDepth) - 1);
}

/**
 * 解码 PNG 为 8 位 RGBA。
 * 支持位深 1/2/4/8/16、颜色类型 0/2/3/4/6、隔行 0/1。
 * @returns { width, height, hasAlpha, data: Buffer(RGBA) }
 */
function decodePng(buf) {
	const chunks = readPngChunks(buf);
	const ihdr = chunks.find((c) => c.type === "IHDR").data;
	if (ihdr.length < 13) throw new Error("sharp-shim: PNG IHDR 长度非法");
	const width = ihdr.readUInt32BE(0);
	const height = ihdr.readUInt32BE(4);
	const bitDepth = ihdr[8];
	const colourType = ihdr[9];
	const compression = ihdr[10];
	const filterMethod = ihdr[11];
	const interlace = ihdr[12];
	if (width === 0 || height === 0) throw new Error("sharp-shim: PNG 尺寸为 0");
	if (compression !== 0 || filterMethod !== 0) throw new Error("sharp-shim: PNG 压缩/滤波方法不支持");
	if (![1, 2, 4, 8, 16].includes(bitDepth)) throw new Error(`sharp-shim: PNG 位深 ${bitDepth} 不支持`);
	if (interlace !== 0 && interlace !== 1) throw new Error(`sharp-shim: PNG 隔行方式 ${interlace} 不支持`);
	const channels = channelsFor(colourType);
	if (bitDepth < 8 && colourType !== 0 && colourType !== 3) {
		throw new Error("sharp-shim: 位深 <8 仅支持灰度与调色板 PNG");
	}

	// 调色板
	let palette = null;
	const plte = chunks.find((c) => c.type === "PLTE");
	if (colourType === 3) {
		if (plte === undefined) throw new Error("sharp-shim: 调色板 PNG 缺少 PLTE");
		palette = plte.data;
	}
	// tRNS：给调色板/灰度提供 alpha
	const trns = chunks.find((c) => c.type === "tRNS");
	let trnsPalette = null;
	let trnsGray = null;
	if (trns !== undefined) {
		if (colourType === 3) trnsPalette = trns.data;
		else if (colourType === 0 && trns.data.length >= 2) trnsGray = trns.data.readUInt16BE(0);
	}

	const idat = Buffer.concat(chunks.filter((c) => c.type === "IDAT").map((c) => c.data));
	if (idat.length === 0) throw new Error("sharp-shim: PNG 缺少 IDAT");
	let inflated;
	try {
		inflated = zlib.inflateSync(idat);
	} catch (error) {
		throw new Error(`sharp-shim: PNG IDAT 无法解压（文件已损坏）：${error.message}`);
	}

	const hasAlphaChannel = colourType === 4 || colourType === 6;
	const hasTrns = trns !== undefined;
	const out = Buffer.alloc(width * height * 4);
	const maxValue = (1 << bitDepth) - 1;
	const scale = (value) => (bitDepth === 8 ? value : bitDepth === 16 ? value : Math.round((value / maxValue) * 255));

	/** 把一条未滤波的扫描线里的样本写进输出。 */
	const writePixel = (x, y, row, sampleIndex) => {
		let r, g, b, a = 255;
		if (colourType === 0) {
			const v = readSample(row, sampleIndex, bitDepth);
			const gray = scale(v);
			r = g = b = gray;
			if (trnsGray !== null) a = v === trnsGray ? 0 : 255;
		} else if (colourType === 2) {
			r = readSample(row, sampleIndex * 3, bitDepth);
			g = readSample(row, sampleIndex * 3 + 1, bitDepth);
			b = readSample(row, sampleIndex * 3 + 2, bitDepth);
			r = scale(r); g = scale(g); b = scale(b);
		} else if (colourType === 3) {
			const idx = readSample(row, sampleIndex, bitDepth);
			const base = idx * 3;
			if (base + 2 >= palette.length) throw new Error("sharp-shim: PNG 调色板索引越界");
			r = palette[base]; g = palette[base + 1]; b = palette[base + 2];
			if (trnsPalette !== null) a = idx < trnsPalette.length ? trnsPalette[idx] : 255;
		} else if (colourType === 4) {
			const gray = scale(readSample(row, sampleIndex * 2, bitDepth));
			r = g = b = gray;
			a = scale(readSample(row, sampleIndex * 2 + 1, bitDepth));
		} else {
			r = scale(readSample(row, sampleIndex * 4, bitDepth));
			g = scale(readSample(row, sampleIndex * 4 + 1, bitDepth));
			b = scale(readSample(row, sampleIndex * 4 + 2, bitDepth));
			a = scale(readSample(row, sampleIndex * 4 + 3, bitDepth));
		}
		const o = (y * width + x) * 4;
		out[o] = r; out[o + 1] = g; out[o + 2] = b; out[o + 3] = a;
	};

	/** 反滤波一趟并逐像素写出。返回消费掉的字节数。 */
	const consumePass = (raw, passWidth, passHeight, x0, y0, dx, dy) => {
		const bpp = Math.max(1, Math.ceil((channels * bitDepth) / 8));
		const rowBytes = Math.ceil((passWidth * channels * bitDepth) / 8);
		let prev = Buffer.alloc(rowBytes);
		let cursor = 0;
		for (let py = 0; py < passHeight; py++) {
			if (cursor + 1 + rowBytes > raw.length) throw new Error("sharp-shim: PNG 像素数据不足（文件被截断）");
			const filterType = raw[cursor++];
			const row = Buffer.from(raw.subarray(cursor, cursor + rowBytes));
			cursor += rowBytes;
			// PNG 反滤波（5 种）
			for (let i = 0; i < rowBytes; i++) {
				const a = i >= bpp ? row[i - bpp] : 0;
				const b = prev[i];
				const c = i >= bpp ? prev[i - bpp] : 0;
				switch (filterType) {
					case 0: break;
					case 1: row[i] = (row[i] + a) & 0xff; break;
					case 2: row[i] = (row[i] + b) & 0xff; break;
					case 3: row[i] = (row[i] + ((a + b) >> 1)) & 0xff; break;
					case 4: {
						const p = a + b - c;
						const pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c);
						const pred = pa <= pb && pa <= pc ? a : pb <= pc ? b : c;
						row[i] = (row[i] + pred) & 0xff;
						break;
					}
					default: throw new Error(`sharp-shim: PNG 滤波类型 ${filterType} 非法`);
				}
			}
			for (let px = 0; px < passWidth; px++) writePixel(x0 + px * dx, y0 + py * dy, row, px);
			prev = row;
		}
		return cursor;
	};

	if (interlace === 0) {
		consumePass(inflated, width, height, 0, 0, 1, 1);
	} else {
		let cursor = 0;
		for (const pass of ADAM7) {
			const pw = Math.ceil((width - pass.x0) / pass.dx);
			const ph = Math.ceil((height - pass.y0) / pass.dy);
			if (pw <= 0 || ph <= 0) continue;
			cursor += consumePass(inflated.subarray(cursor), pw, ph, pass.x0, pass.y0, pass.dx, pass.dy);
		}
	}
	return { width, height, hasAlpha: hasAlphaChannel || hasTrns, data: out };
}

/** 写一个 PNG chunk（自动计算 CRC）。 */
function pngChunk(type, data) {
	const length = Buffer.alloc(4);
	length.writeUInt32BE(data.length);
	const typed = Buffer.concat([Buffer.from(type, "ascii"), data]);
	const crc = Buffer.alloc(4);
	crc.writeUInt32BE(crc32(typed));
	return Buffer.concat([length, typed, crc]);
}

/** 把 RGBA 编码成 PNG（8 位、非隔行、逐行选最优滤波）。 */
function encodePng({ width, height, data, hasAlpha }) {
	const colourType = hasAlpha ? 6 : 2;
	const channels = hasAlpha ? 4 : 3;
	const stride = width * channels;
	const raw = Buffer.alloc(height * (1 + stride));
	for (let y = 0; y < height; y++) {
		const srcBase = y * width * 4;
		const row = Buffer.alloc(stride);
		for (let x = 0; x < width; x++) {
			const s = srcBase + x * 4;
			const d = x * channels;
			row[d] = data[s]; row[d + 1] = data[s + 1]; row[d + 2] = data[s + 2];
			if (hasAlpha) row[d + 3] = data[s + 3];
		}
		// 逐行试 5 种滤波，取绝对值和最小者（标准做法，压缩率接近最优）
		let bestType = 0, best = null, bestScore = Infinity;
		for (let type = 0; type <= 4; type++) {
			const candidate = filterRow(row, y === 0 ? null : null, type, channels);
			let score = 0;
			for (let i = 0; i < candidate.length; i++) score += candidate[i] < 128 ? candidate[i] : 256 - candidate[i];
			if (score < bestScore) { bestScore = score; bestType = type; best = candidate; }
		}
		raw[y * (1 + stride)] = bestType;
		best.copy(raw, y * (1 + stride) + 1);
	}
	const ihdr = Buffer.alloc(13);
	ihdr.writeUInt32BE(width, 0);
	ihdr.writeUInt32BE(height, 4);
	ihdr[8] = 8;
	ihdr[9] = colourType;
	return Buffer.concat([
		PNG_SIGNATURE,
		pngChunk("IHDR", ihdr),
		pngChunk("IDAT", zlib.deflateSync(raw, { level: 6 })),
		pngChunk("IEND", Buffer.alloc(0))
	]);
}

/**
 * 对一条扫描线做 PNG 滤波。
 * @param row - 原始扫描线（无滤波字节）。
 * @param prev - 上一条原始扫描线；没有则传 null。
 * @param type - 滤波类型 0..4。
 * @param bpp - 每像素字节数。
 * @returns 滤波后的扫描线。
 */
function filterRow(row, prev, type, bpp) {
	const out = Buffer.alloc(row.length);
	for (let i = 0; i < row.length; i++) {
		const a = i >= bpp ? row[i - bpp] : 0;
		const b = prev === null ? 0 : prev[i];
		const c = prev === null || i < bpp ? 0 : prev[i - bpp];
		let pred;
		switch (type) {
			case 0: pred = 0; break;
			case 1: pred = a; break;
			case 2: pred = b; break;
			case 3: pred = (a + b) >> 1; break;
			default: {
				const p = a + b - c;
				const pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c);
				pred = pa <= pb && pa <= pc ? a : pb <= pc ? b : c;
			}
		}
		out[i] = (row[i] - pred) & 0xff;
	}
	return out;
}

/** 面积平均缩小 / 双线性放大，输出 8 位 RGBA。 */
function resizeRgba(img, targetWidth, targetHeight) {
	const { width, height, data } = img;
	if (targetWidth === width && targetHeight === height) return img;
	const out = Buffer.alloc(targetWidth * targetHeight * 4);
	const scaleX = width / targetWidth;
	const scaleY = height / targetHeight;
	if (targetWidth <= width && targetHeight <= height) {
		// 缩小：面积平均（对截图 / 线稿比双线性更干净）
		for (let y = 0; y < targetHeight; y++) {
			const y0 = Math.floor(y * scaleY);
			const y1 = Math.max(y0 + 1, Math.min(height, Math.ceil((y + 1) * scaleY)));
			for (let x = 0; x < targetWidth; x++) {
				const x0 = Math.floor(x * scaleX);
				const x1 = Math.max(x0 + 1, Math.min(width, Math.ceil((x + 1) * scaleX)));
				let r = 0, g = 0, b = 0, a = 0, n = 0;
				for (let sy = y0; sy < y1; sy++) {
					for (let sx = x0; sx < x1; sx++) {
						const s = (sy * width + sx) * 4;
						r += data[s]; g += data[s + 1]; b += data[s + 2]; a += data[s + 3]; n++;
					}
				}
				const o = (y * targetWidth + x) * 4;
				out[o] = Math.round(r / n); out[o + 1] = Math.round(g / n);
				out[o + 2] = Math.round(b / n); out[o + 3] = Math.round(a / n);
			}
		}
		return { width: targetWidth, height: targetHeight, hasAlpha: img.hasAlpha, data: out };
	}
	// 放大 / 混合：双线性
	for (let y = 0; y < targetHeight; y++) {
		const sy = Math.min(height - 1, ((y + 0.5) * scaleY) - 0.5);
		const y0 = Math.max(0, Math.floor(sy));
		const y1 = Math.min(height - 1, y0 + 1);
		const wy = sy - y0;
		for (let x = 0; x < targetWidth; x++) {
			const sx = Math.min(width - 1, ((x + 0.5) * scaleX) - 0.5);
			const x0 = Math.max(0, Math.floor(sx));
			const x1 = Math.min(width - 1, x0 + 1);
			const wx = sx - x0;
			const o = (y * targetWidth + x) * 4;
			for (let ch = 0; ch < 4; ch++) {
				const p00 = data[(y0 * width + x0) * 4 + ch];
				const p10 = data[(y0 * width + x1) * 4 + ch];
				const p01 = data[(y1 * width + x0) * 4 + ch];
				const p11 = data[(y1 * width + x1) * 4 + ch];
				const top = p00 + (p10 - p00) * wx;
				const bottom = p01 + (p11 - p01) * wx;
				out[o + ch] = Math.round(top + (bottom - top) * wy);
			}
		}
	}
	return { width: targetWidth, height: targetHeight, hasAlpha: img.hasAlpha, data: out };
}

//#endregion

//#region 元数据

function describe(buf) {
	const probed = probeImageBytes(buf);
	if (probed === null) throw new Error("sharp-shim: 不支持的图像数据（无法识别文件头）");
	return probed;
}

/**
 * sharp.metadata() 的替身返回值。
 * hasAlpha 对 PNG 来自 IHDR 颜色类型 + tRNS（真实事实），不再是 undefined ——
 * 否则 `encodingLadder()` 会一律选 JPEG，对带透明通道的图是错的。
 */
function metadataOf(buf) {
	const probed = describe(buf);
	if (probed.format === "png") {
		const ihdr = readPngChunks(buf).find((c) => c.type === "IHDR").data;
		const colourType = ihdr[9];
		const chunks = readPngChunks(buf);
		return {
			format: "png",
			width: probed.width,
			height: probed.height,
			pages: chunks.some((c) => c.type === "acTL") ? 2 : 1, // APNG 视为多帧
			depth: ihdr[8] === 16 ? "ushort" : "uchar",
			space: "srgb",
			hasAlpha: colourType === 4 || colourType === 6 || chunks.some((c) => c.type === "tRNS")
		};
	}
	return {
		format: probed.format,
		width: probed.width,
		height: probed.height,
		pages: 1,
		depth: "uchar",
		space: "srgb",
		hasAlpha: false
	};
}

function infoOf(buf) {
	const probed = describe(buf);
	return {
		width: probed.width,
		height: probed.height,
		format: probed.format,
		mediaType: MEDIA_TYPES[probed.format]
	};
}

//#endregion

/**
 * 与 sharp 相同的链式调用面。
 *
 * ⚠️ 关键约定（v1.15.1 起）：`toBuffer()` 返回的字节格式永远与 `info.mediaType` 一致 ——
 * PNG 走真实编解码；其它格式无法在纯 JS 里转换时，**原样返回但如实声明真实格式**，
 * 绝不按调用方请求的格式谎报。调用方（`encode()`）据此声明，故「声明 == 实际字节」恒成立。
 */
class Pipeline {
	#bytes;
	#format;
	#decodeCache;
	#resize;

	constructor(bytes) {
		this.#bytes = bytes;
		this.#format = describe(bytes).format;
		this.#decodeCache = null;
		this.#resize = null;
	}

	clone() {
		const copy = new Pipeline(this.#bytes);
		copy.#decodeCache = this.#decodeCache;
		copy.#resize = this.#resize;
		return copy;
	}

	#decoded() {
		if (this.#format !== "png") throw new Error(`sharp-shim: 纯 JS 解码仅支持 PNG（当前 ${this.#format}）`);
		if (this.#decodeCache === null) this.#decodeCache = decodePng(this.#bytes);
		return this.#decodeCache;
	}

	/** EXIF 方向：PNG 无 EXIF 方向，其它格式不做像素处理 → 空操作。 */
	rotate() {
		return this;
	}

	toColourspace() {
		return this;
	}

	/** 真实缩放（PNG）。宽高都可省略，语义与 sharp 的 fit:inside + withoutEnlargement 一致。 */
	resize(options = {}) {
		if (this.#format !== "png") {
			this.#resize = options;
			return this;
		}
		const src = this.#decoded();
		const wantWidth = options.width;
		const wantHeight = options.height;
		const noEnlarge = options.withoutEnlargement === true;
		let w = src.width, h = src.height;
		if (wantWidth !== undefined && wantHeight !== undefined) {
			if (options.fit === "fill") { w = wantWidth; h = wantHeight; }
			else {
				const scale = Math.min(wantWidth / src.width, wantHeight / src.height);
				w = Math.max(1, Math.round(src.width * scale));
				h = Math.max(1, Math.round(src.height * scale));
			}
		} else if (wantWidth !== undefined) {
			const scale = wantWidth / src.width;
			w = wantWidth; h = Math.max(1, Math.round(src.height * scale));
		} else if (wantHeight !== undefined) {
			const scale = wantHeight / src.height;
			h = wantHeight; w = Math.max(1, Math.round(src.width * scale));
		}
		if (noEnlarge && (w > src.width || h > src.height)) {
			w = src.width; h = src.height;
		}
		this.#resize = { width: w, height: h };
		return this;
	}

	trim() {
		return this;
	}

	withMetadata() {
		return this;
	}

	webp() {
		return this;
	}

	jpeg() {
		return this;
	}

	png() {
		return this;
	}

	async metadata() {
		return metadataOf(this.#bytes);
	}

	/**
	 * 像素访问。`detectImage()` 用 `await image.raw().toBuffer()` 做完整性校验：
	 *  - PNG：真实解码 → **损坏的 PNG 会在这里抛错**（这是病症 A 的根治点）；
	 *  - 其它格式（JPEG/WebP/GIF）：纯 JS 无法解码，**如实返回原始字节**而不抛错。
	 *    （切记不能抛：上游对**所有**格式都走这道校验，抛错会把全部 JPEG 一起拒掉。）
	 */
	raw() {
		const self = this;
		return {
			async toBuffer() {
				if (self.#format === "png") return self.#decoded().data;
				return self.#bytes;
			}
		};
	}

	/**
	 * 产出字节。
	 * PNG：应用缩放后真实编码（必要时保留 alpha）；
	 * 其它格式：原样返回，并如实声明**真实**格式与源尺寸。
	 */
	async toBuffer(options) {
		if (this.#format === "png") {
			const src = this.#decoded();
			const sized = this.#resize === null
				? src
				: resizeRgba(src, this.#resize.width, this.#resize.height);
			const data = encodePng(sized);
			return options?.resolveWithObject === true
				? { data, info: { width: sized.width, height: sized.height, format: "png", mediaType: "image/png" } }
				: data;
		}
		const info = infoOf(this.#bytes);
		return options?.resolveWithObject === true ? { data: this.#bytes, info } : this.#bytes;
	}
}

/**
 * sharp 替身入口，签名与 sharp 兼容。
 * @param input - 待处理的编码图像字节。
 * @returns 链式管线对象。
 */
export default function sharp(input) {
	return new Pipeline(toBytes(input));
}

export { probeImageBytes, decodePng, encodePng, readPngChunks };
